class AppModel {  final int id;  final String title;  final String description;  AppModel({required this.id, required this.title, required this.description});  factory AppModel.fromJson(Map<String, dynamic> json) {    return AppModel(      id: json['id'],      title: json['title'],      description: json['description'],    );  }  Map<String, dynamic> toJson() {    return {      'id': id,      'title': title,      'description': description,    };  }}